   622  /// An immutable JavaScript primitive consisting of a pointer to an
   623  /// ExternalStringPrimitive and a length. This is the result of a concatenation
   624  /// operation, where the referenced ExternalStringPrimitive contains a growing
   625  /// std::string. Each subsequent concatenation appends data to the std::string
   626  /// and allocates a new BufferedStringPrimitive referring to a prefix of it.
   627  ///
   628  /// A degenerate case could result from code that keeps a reference only to an
   629  /// early stage in the "concatenation chain", because it would keep the whole
   630  /// large string alive. Something like this:
   631  /// \code
   632  ///    globalThis.prop = x + " ";
   633  ///    print(globalThis.prop + largeString);
   634  /// \endcode
   635  /// \c globalThis.prop will keep the whole string alive, even though we no
   636  /// longer need the \c largeString suffix.
   637  ///
   638  /// The probability of this happening is not high, but it is possible. One way
   639  /// to adress this in the future is to create new ExternalStringPrimitive after
   640  /// a  certain amount of resizing. In this way each stage of the concatenation
   641  /// has an upper bound of the amount of extra memory it can keep alive.
   642  template <typename T>
   643  class BufferedStringPrimitive final : public StringPrimitive {
   644    friend class IdentifierTable;
   645    friend class StringBuilder;
   646    friend class StringPrimitive;
   647    friend PseudoHandle<StringPrimitive> internalConcatStringPrimitives(
   648        Runtime *runtime,
   649        Handle<StringPrimitive> leftHnd,
   650        Handle<StringPrimitive> rightHnd);
   651    friend void BufferedASCIIStringPrimitiveBuildMeta(
   652        const GCCell *cell,
   653        Metadata::Builder &mb);
   654    friend void BufferedUTF16StringPrimitiveBuildMeta(
   655        const GCCell *cell,
   656        Metadata::Builder &mb);
   657
   658    using Ref = llvh::ArrayRef<T>;
   659    using StdString = std::basic_string<T>;
   660
   661    /// \return the cell kind for this string.
   662    static constexpr CellKind getCellKind() {
   663      return std::is_same<T, char16_t>::value
   664          ? CellKind::BufferedUTF16StringPrimitiveKind
   665          : CellKind::BufferedASCIIStringPrimitiveKind;
   666    }
