   668   public:
   669  #ifdef HERMESVM_SERIALIZE
   670    template <typename>
   671    friend void serializeConcatStringImpl(Serializer &s, const GCCell *cell);
   672
   673    template <typename>
   674    friend void deserializeConcatStringImpl(Deserializer &d);
   675  #endif
   676
   677    static bool classof(const GCCell *cell) {
   678      return cell->getKind() == BufferedStringPrimitive::getCellKind();
   679    }
