   681  #ifdef UNIT_TEST
   682    /// Expose the concatenation buffer for unit tests.
   683    ExternalStringPrimitive<T> *testGetConcatBuffer() const {
   684      return vmcast<ExternalStringPrimitive<T>>(concatBufferHV_);
