   691    /// Construct a BufferedStringPrimitive with the specified length \p length
   692    /// and the associated concatenation buffer \p storage. Note that the length
   693    /// of the primitive may be smaller than the length of the buffer.
   694    BufferedStringPrimitive(
   695        Runtime *runtime,
   696        uint32_t length,
   697        ExternalStringPrimitive<T> *concatBuffer)
   698        : StringPrimitive(
   699              runtime,
   700              &vt,
   701              sizeof(BufferedStringPrimitive<T>),
   702              length) {
   703      concatBufferHV_.set(
   704          HermesValue::encodeObjectValue(concatBuffer), &runtime->getHeap());
   705      assert(
   706          concatBuffer->contents_.size() >= length &&
   707          "length exceeds size of concatenation buffer");
   708    }
