   719    /// BufferedStringPrimitive representing the result.
   720    /// \pre The types must be compatible (cannot append UTF16 to ASCII) and the
   721    /// combined length must have been validated.
   722    /// \return the new BufferedStringPrimitive representing the result.
   723    static PseudoHandle<StringPrimitive> append(
   724        Handle<BufferedStringPrimitive<T>> selfHnd,
   725        Runtime *runtime,
   726        Handle<StringPrimitive> rightHnd);
