   730    /// \p rightHnd and allocate a new BufferedStringPrimitive to represent the
   731    /// result.
   732    /// \pre The types must be compatible with respect to T (cannot append UTF16
   733    /// to ASCII) and the combined length must have been validated.
   734    /// \return a new BufferedStringPrimitive representing the result.
   735    static PseudoHandle<StringPrimitive> create(
   736        Runtime *runtime,
   737        Handle<StringPrimitive> leftHnd,
   738        Handle<StringPrimitive> rightHnd);
